class FHNETConnectionError(Exception):
    """ Raised when connection to FHNET is failed. """
    pass


class ExpectedPhraseNotFoundError(Exception):
    """ Raised when expected phrase is not in shell output within the specified timeout"""
    pass


class RmodConnectionError(Exception):
    """ Raised when connection to RMOD is failed. """
    pass


class BTSConnectionError(Exception):
    """ Raised when connection to BTS is failed. """
    pass


class RmodLogoutError(Exception):
    """ Raised when logout from RMOD is failed. """
    pass


class RmodLogsCollectionError(Exception):
    """ Raised when collect logs on RMOD (log -c full -a -z) is failed. """
    pass


class DownloadFileError(Exception):
    """ Raised when file downloading is failed. """
    pass


class UploadFileError(Exception):
    """ Raised when file uploading is failed. """
    pass


class FHNETContainerNotFound(Exception):
    """ Raised when SMOD container cannot be found. """
    pass


class UnacceptablePhraseError(Exception):
    """ Raised when unacceptable phrase is found in shell output. """
    pass


class ArgValueEqualsZero(Exception):
    """ Raised when argument equals zero. """
    pass


class RepetitionIntervalGreaterThanTimeout(Exception):
    """ Raised when repetition_interval is greater than timeout. """
    pass


class InvalidSourceBtsError(Exception):
    """ Raised when invalid source BTS provided. """
    pass


class InvalidRmodProtocolError(Exception):
    """ Raised when invalid RMOD protocol type provided. """
    pass
